    targetsCaveat: "\u0647\u0630\u0647 \u0623\u0647\u062F\u0627\u0641 \u0627\u0644\u062A\u0648\u0638\u064A\u0641 \u0627\u0644\u062A\u064A \u0623\u0639\u0644\u0646\u062A\u0647\u0627 \u0627\u0644\u062C\u0647\u0627\u062A \u0627\u0644\u0645\u0637\u0648\u0651\u0631\u0629. \u0648\u0642\u062F \u062A\u0648\u0642\u0651\u0641 \u0628\u0639\u0636 \u0627\u0644\u0645\u0634\u0627\u0631\u064A\u0639 \u0627\u0644\u0639\u0645\u0644\u0627\u0642\u0629 \u0623\u0648 \u062A\u0642\u0644\u0651\u0635 \u0646\u0637\u0627\u0642\u0647 \u0645\u0646\u0630 \u0630\u0644\u0643 \u0627\u0644\u062D\u064A\u0646\u060C \u0644\u0630\u0627 \u062A\u0628\u0627\u0644\u063A \u0647\u0630\u0647 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0641\u064A \u062A\u0642\u062F\u064A\u0631 \u0627\u0644\u062A\u0648\u0642\u0639\u0627\u062A \u0627\u0644\u062D\u0627\u0644\u064A\u0629. \u0648\u062A\u0631\u0643\u0651\u0632 \u0627\u0633\u062A\u0631\u0627\u062A\u064A\u062C\u064A\u0629 \u0635\u0646\u062F\u0648\u0642 \u0627\u0644\u0627\u0633\u062A\u062B\u0645\u0627\u0631\u0627\u062A \u0627\u0644\u0639\u0627\u0645\u0629 2026\u20132030\u060C \u0627\u0644\u0645\u0639\u062A\u0645\u062F\u0629 \u0641\u064A 15 \u0623\u0628\u0631\u064A\u0644 2026\u060C \u0639\u0644\u0649 \u0627\u0644\u0639\u0648\u0627\u0626\u062F \u0627\u0644\u0645\u0627\u0644\u064A\u0629 \u0648\u0645\u0634\u0627\u0631\u0643\u0629 \u0627\u0644\u0642\u0637\u0627\u0639 \u0627\u0644\u062E\u0627\u0635.",
